import{z as E,x as p,o as e,c as d,q as r,j as s,D as t,d as n,s as i,S as l}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"NTP","description":"","frontmatter":{"title":"NTP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ntp.md","filePath":"cs/ntp.md","lastUpdated":1791063341000}'),B={name:"cs/ntp.md"};function T(_,a,A,c,P,S){const o=p("Mermaid");return e(),d("div",null,[a[2]||(a[2]=r('<h1 id="ntp" tabindex="-1">NTP <a class="header-anchor" href="#ntp" aria-label="Permalink to &quot;NTP&quot;">​</a></h1><div class="epigraph"><p>NTP 用四时间戳估计往返与偏移，把主机时钟循向更上层的源；分层 stratum 防止环，精度到毫秒级常见。</p><footer>—— 据 RFC 5905 NTPv4；Mills, Computer Network Time Synchronization 整理</footer></div><p><a href="/cs/dnssec">DNSSEC</a> 的签名有效期、<a href="/cs/http-tls-entry">TLS</a> 的证书期、<a href="/cs/ssh-protocol">上一课</a>的证书校验，全都压在一个前提上：主机时钟合理。本课补这个前提——<strong>NTP</strong>：偏移估计与分层拓扑。不是 GPS 那类微秒级来源；PTP 留给下一课，本课不把它写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>晶振会漂，时钟必须周期校准。NTP 的核心是一次交换四个时间戳：客户发 \\(t_1\\)，服务器收 \\(t_2\\)、回 \\(t_3\\)，客户收 \\(t_4\\)；偏移 \\(\\theta\\approx((t_2-t_1)+(t_3-t_4))/2\\)，往返延迟 \\(\\delta=(t_4-t_1)-(t_3-t_2)\\)。客户对多个源多次采样，滤波择优后缓慢驯服本地钟。拓扑分层：Stratum 1 直连原子钟或 GPS，往下逐层递增，分层既防环也逐层累积误差。协议可认证：对称密钥或 NTS（点名）。安全后果要记牢：被劫持的时间源能整体挪动 DNSSEC 的有效期窗口与票据期限，等效于攻破这些系统。</p><p><span class="marginnote">数字实例：设客户 \\(t_1=0\\) 毫秒发出，服务端 \\(t_2=10\\) 收到、\\(t_3=12\\) 回，客户 \\(t_4=20\\) 收到。偏移 \\(\\theta=(10+(12-20))/2=1\\) 毫秒——你的表慢 1 毫秒；往返 \\(\\delta=20-(12-10)=18\\) 毫秒。分子再大也只要小学加减法，难的是假设「去和回一样快」。</span></p><p><code>date</code> 只是读钟，不含估计与驯服，不是协议。</p><p><span class="marginnote">RFC 5905。闰秒处理是边界。本课不把钟控环 PID 写完。</span></p><h3 id="毫秒级驯服" tabindex="-1">毫秒级驯服 <a class="header-anchor" href="#毫秒级驯服" aria-label="Permalink to &quot;毫秒级驯服&quot;">​</a></h3><p>四时间戳公式假设上下行路径对称，非对称路径直接变成 \\(\\theta\\) 的偏差，精度因此停在毫秒级而非微秒级。多源采样防单点：公网单台 NTP 服务器不能当唯一源。时间错的连带伤害不止 DNSSEC，还有 TCP PAWS——时间戳倒退的段会被当旧段丢弃。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是读一次交换怎么变成估计：四时间戳给出偏移与延迟两个量。与 ping 对照：两者都测 RTT，但 ping 只要总和，NTP 要把 RTT 拆成偏移，于是多了对称假设；卫星链路与流量工程造成的非对称路径就落在这里变成误差。</p>',12)),(e(),s(l,null,{default:t(()=>[i(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20T1%5B%22%E5%AE%A2%E6%88%B7%E5%8F%91%22%5D%20--%3E%20T2%5B%22%E6%9C%8D%E5%8A%A1%E6%94%B6%22%5D%0A%20%20T2%20--%3E%20T3%5B%22%E6%9C%8D%E5%8A%A1%E5%8F%91%22%5D%0A%20%20T3%20--%3E%20T4%5B%22%E5%AE%A2%E6%88%B7%E6%94%B6%22%5D%0A%20%20T4%20--%3E%20OFF%5B%22%E4%BC%B0%E5%81%8F%E7%A7%BB%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p><span class="marginnote">直觉类比：四时间戳像两人对表。你说「我 0 点整发的话」，对方回「我 0 点 10 收到、0 点 12 回信」，你在 0 点 20 读到——去回各按 10、8 毫秒算，折中出「你的表慢约 1 毫秒」。<code>ping</code> 只报总账 20，NTP 要把总账拆成「钟差」与「路程」，才多出对称假设这条软肋。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制上，数据中心自建本地 stratum，只让少数几台从公网同步，下游用内网源减掉公网 RTT 噪声；防火墙要放行 123/UDP。安全历史上，<code>monlist</code> 查询曾被用作 DoS 放大器，当代实现应默认关闭。与 BDP 没有直接关系，但时间错会让 TCP 时间戳触发 PAWS 误杀，间接伤吞吐。VM 热迁移后时钟会跳，要重新驯服，接在 OS 的时钟校正层。</p><p><span class="marginnote">术语翻译：<code>monlist</code> 就是「把我认识的所有对端名单发给你」的调试查询——请求几十字节、响应可达几 KB，「放大攻击」就是用这种小请求骗大响应去淹没别人；所以当代 NTP 实现默认关掉它。</span></p>',4)),(e(),s(l,null,{default:t(()=>[i(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20S0%5B%22Stratum%200%3A%20GPS%20%2F%20%E5%8E%9F%E5%AD%90%E9%92%9F%22%5D%20--%3E%20S1%5B%22Stratum%201%3A%20%E7%9B%B4%E8%BF%9E%E6%97%B6%E9%92%9F%E7%9A%84%E5%B0%91%E6%95%B0%E5%87%A0%E5%8F%B0%22%5D%0A%20%20S1%20--%3E%20S2%5B%22Stratum%202%3A%20%E6%95%B0%E6%8D%AE%E4%B8%AD%E5%BF%83%E8%87%AA%E6%9C%89%20NTP%22%5D%0A%20%20S2%20--%3E%20S3%5B%22Stratum%203%2B%3A%20%E5%86%85%E7%BD%91%E4%B8%BB%E6%9C%BA%22%5D%0A%20%20S2%20-.-%3E%7C%22%E4%BA%92%E4%B8%BA%E5%A4%87%E4%BB%BD%E6%BA%90%2C%20%E6%8B%A9%E4%BC%98%22%7C%20S2%0A%20%20S3%20-.-%3E%7C%22%E4%B8%8B%E5%B1%82%E6%B0%B8%E4%B8%8D%E7%BB%99%E4%B8%8A%E5%B1%82%E4%BE%9B%E6%97%B6%2C%20%E6%95%85%E4%B8%8D%E6%88%90%E7%8E%AF%22%7C%20S2%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 NTS 握手全文，点名即可。PTP 是下一课。后课默认：NTP 做毫秒级驯服，路径不对称是主要误差源；只信一台公网 NTP 是单点。</p><p>下一课<a href="/cs/ptp-precision-time">PTP</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>四时间戳估计偏移与往返延迟。</li><li>Stratum 分层防环，多源采样防单点。</li><li>安全两头：认证时间源，关闭放大查询。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 5905；Mills。</li></ul>',5))])}const u=E(B,[["render",T]]);export{m as __pageData,u as default};
